"""Two synthetic emails in one batch through the exact production guard/dispatch.
Creates recipientless seed drafts to obtain real Gmail threads, then reply drafts.
Never sends messages. Retain IDs for replay verification; do not blindly rerun.
"""
import json,copy
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];P=ROOT.parent/'work/implementation-private'
env=json.loads((P/'module4-environment.json').read_text());w=json.loads((P/'module4-drafts/gmail_inbox.json').read_text())
w['name']='Aurora M4 - Prueba lote dos correos';w['nodes']=[n for n in w['nodes'] if n['name']!='Gmail Trigger'];w['connections'].pop('Gmail Trigger')
def node(name,typ,p,x,y=800,v=1,**kw):return {'id':name,'name':name,'type':typ,'typeVersion':v,'position':[x,y],'parameters':p,**kw}
def edge(a,b):w['connections'][a]={'main':[[{'node':b,'type':'main','index':0}]]}
w['nodes'] += [node('Prueba manual','n8n-nodes-base.manualTrigger',{},0),node('Dos casos sinteticos','n8n-nodes-base.code',{'jsCode':"return ['A','B'].map(key=>({json:{key,subject:'M4 prueba sintetica '+key}}));"},240,v=2),node('Crear hilos de prueba','n8n-nodes-base.gmail',{'resource':'draft','operation':'create','subject':'={{ $json.subject }}','emailType':'text','message':'Entrada sintetica para verificar aislamiento. No enviar.','options':{}},480,v=2.1,credentials={'gmailOAuth2':env['gmail_credential']}),node('Simular lote entrante','n8n-nodes-base.code',{'jsCode':"return $input.all().map((item,i)=>{const key=i===0?'A':'B';if(!item.json.message?.threadId)throw Error('SEED_THREAD_MISSING');return {json:{id:'m4-batch-v1-'+key,threadId:item.json.message.threadId,from:'Prueba '+key+' <aurora-m4-batch-'+key.toLowerCase()+'@example.com>',subject:'M4 prueba sintetica '+key,text:i===0?'Cuánto cuesta el manicure básico?':'Cuánto dura el manicure básico?',headers:{'Auto-Submitted':'no'},seed_draft_id:item.json.id}};});"},720,v=2),node('Leer borradores reales','n8n-nodes-base.gmail',{'resource':'draft','operation':'get','messageId':'={{ $json.draft_id }}','options':{'downloadAttachments':False}},1200,v=2.1,credentials={'gmailOAuth2':env['gmail_credential']}),node('Verificar aislamiento','n8n-nodes-base.code',{'jsCode':"const inputs=$('Simular lote entrante').all().map(i=>i.json),deliveries=$('Procesar correo individual').all().map(i=>i.json),drafts=$input.all().map(i=>i.json);const rows=drafts.map((d,i)=>{const expected=inputs[i];const to=d.to?.text||d.headers?.to||'';return {case_id:i===0?'A':'B',request_id:'gmail:'+expected.id,expected_recipient:expected.from,actual_recipient:to,expected_thread:expected.threadId,actual_thread:d.threadId,draft_id:d.id,seed_draft_id:expected.seed_draft_id,status:deliveries[i]?.status,body:d.text||d.textPlain||'',pass:deliveries[i]?.status==='completed'&&String(to).toLowerCase().includes('aurora-m4-batch-'+(i===0?'a':'b')+'@example.com')&&d.threadId===expected.threadId};});return [{json:{test_id:'m4-two-message-batch',pass:rows.length===2&&rows.every(r=>r.pass)&&rows[0].draft_id!==rows[1].draft_id,results:rows,external_messages_sent:0}}];"},1440,v=2)]
for a,b in [('Prueba manual','Dos casos sinteticos'),('Dos casos sinteticos','Crear hilos de prueba'),('Crear hilos de prueba','Simular lote entrante'),('Simular lote entrante','Correo permitido'),('Procesar correo individual','Leer borradores reales'),('Leer borradores reales','Verificar aislamiento')]:edge(a,b)
(P/'module4-drafts/inbox_batch_test.json').write_text(json.dumps(w,ensure_ascii=False,indent=2)+'\n')
